package com.primehr.rsp.evaluation.application;
import com.fasterxml.jackson.core.*; import com.fasterxml.jackson.databind.*; import com.primehr.rsp.domain.*; import com.primehr.rsp.evaluation.api.EvaluationPolicyDtos.*; import com.primehr.rsp.evaluation.domain.*; import com.primehr.rsp.evaluation.infrastructure.*; import com.primehr.rsp.infrastructure.VacancyPublicationRepository; import com.primehr.shared.api.PageResponse; import com.primehr.shared.audit.PrimeHrAuditService; import com.primehr.shared.exception.*; import org.springframework.data.domain.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import java.nio.charset.*; import java.security.*; import java.time.*; import java.util.*; import java.util.function.*; import java.util.stream.*; import java.math.*;
@Service @Transactional public class EvaluationPolicyServiceImpl implements EvaluationPolicyService {
 private final EvaluationPolicyRepository policies;private final EvaluationStageRepository stages;private final EvaluationCriterionRepository criteria;private final PublicationEvaluationPolicyRepository bindings;private final VacancyPublicationRepository publications;private final PrimeHrAuditService audit;private final ObjectMapper json;
 public EvaluationPolicyServiceImpl(EvaluationPolicyRepository p,EvaluationStageRepository s,EvaluationCriterionRepository c,PublicationEvaluationPolicyRepository b,VacancyPublicationRepository v,PrimeHrAuditService a,ObjectMapper j){policies=p;stages=s;criteria=c;bindings=b;publications=v;audit=a;json=j;}
 @Override @Transactional(readOnly=true)public PageResponse<PolicyResponse> list(String agency,int page,int size){page(page,size);return PageResponse.from(policies.findByAgencyId(agency,PageRequest.of(page,size,Sort.by("createdAt").descending())),p->response(agency,p));}
 @Override @Transactional(readOnly=true)public PolicyResponse get(String agency,String id){return response(agency,policy(agency,id));}
 @Override public PolicyResponse create(String agency,SavePolicy r,String correlation){if(r.recordVersion()!=null)throw new IllegalArgumentException("recordVersion must not be supplied when creating");validate(r.stages());String code=r.code().trim().toUpperCase(Locale.ROOT);if(policies.existsByAgencyIdAndNormalizedCodeAndDefinitionVersion(agency,code,1))throw new IllegalArgumentException("Evaluation policy code already exists");EvaluationPolicy p=policies.saveAndFlush(entity(agency,r,1,null));replace(agency,p,r.stages());PolicyResponse after=response(agency,p);audit.record(agency,"CREATE_EVALUATION_POLICY_DRAFT","RSP_EVALUATION_POLICY",p.getId(),1,p.getVersion(),null,after,null,correlation);return after;}
 @Override public PolicyResponse update(String agency,String id,SavePolicy r,String correlation){EvaluationPolicy p=policy(agency,id);version(p.getVersion(),r.recordVersion());validate(r.stages());PolicyResponse before=response(agency,p);p.update(r.code(),r.name(),r.description(),r.meritSelectionPlanReference(),r.roundingScale(),r.roundingMode(),r.tieRule());p=policies.saveAndFlush(p);replace(agency,p,r.stages());PolicyResponse after=response(agency,p);audit.record(agency,"UPDATE_EVALUATION_POLICY_DRAFT","RSP_EVALUATION_POLICY",id,p.getDefinitionVersion(),p.getVersion(),before,after,null,correlation);return after;}
 @Override public PolicyResponse publish(String agency,String id,Publish r,String correlation){EvaluationPolicy p=policy(agency,id);version(p.getVersion(),r.recordVersion());validatePersisted(agency,p.getId());EvaluationPolicy prior=p.getSupersedesId()==null?null:policy(agency,p.getSupersedesId());if(prior!=null&&!r.effectiveFrom().isAfter(prior.getEffectiveFrom()))throw new IllegalArgumentException("A successor must become effective after its predecessor");PolicyResponse before=response(agency,p);p.publish(r.effectiveFrom(),r.effectiveTo(),audit.currentActor(),Instant.now());p=policies.saveAndFlush(p);if(prior!=null){prior.supersede(r.effectiveFrom());policies.saveAndFlush(prior);}PolicyResponse after=response(agency,p);audit.record(agency,"PUBLISH_EVALUATION_POLICY","RSP_EVALUATION_POLICY",id,p.getDefinitionVersion(),p.getVersion(),before,after,null,correlation);return after;}
 @Override public PolicyResponse successor(String agency,String id,Transition r,String correlation){EvaluationPolicy prior=policy(agency,id);version(prior.getVersion(),r.recordVersion());if(prior.getStatus()!=EvaluationPolicy.Status.PUBLISHED)throw new IllegalArgumentException("Only a PUBLISHED policy can have a successor");int next=policies.findByAgencyIdAndNormalizedCodeOrderByDefinitionVersion(agency,prior.getNormalizedCode()).stream().mapToInt(EvaluationPolicy::getDefinitionVersion).max().orElse(0)+1;EvaluationPolicy p=policies.saveAndFlush(new EvaluationPolicy(agency,prior.getCode(),prior.getName(),prior.getDescription(),prior.getMeritSelectionPlanReference(),next,prior.getId(),prior.getRoundingScale(),prior.getRoundingMode(),prior.getTieRule()));copy(agency,prior.getId(),p.getId());PolicyResponse after=response(agency,p);audit.record(agency,"CREATE_EVALUATION_POLICY_SUCCESSOR","RSP_EVALUATION_POLICY",p.getId(),next,p.getVersion(),null,after,null,correlation);return after;}
 @Override public BindingResponse bind(String agency,String publicationId,BindPolicy r,String correlation){if(bindings.existsByAgencyIdAndPublicationId(agency,publicationId))throw new ApplicationConflictException("This vacancy publication already has an immutable evaluation policy binding");VacancyPublication publication=publications.findByIdAndAgencyId(publicationId,agency).orElseThrow(()->new ResourceNotFoundException("Vacancy publication not found"));version(publication.getVersion(),r.publicationRecordVersion());if(publication.getStatus()!=VacancyPublicationStatus.PUBLISHED&&publication.getStatus()!=VacancyPublicationStatus.CLOSED)throw new IllegalArgumentException("Only PUBLISHED or CLOSED vacancies can be bound for evaluation");EvaluationPolicy policy=policy(agency,r.policyId());version(policy.getVersion(),r.policyRecordVersion());if(!policy.effectiveOn(publication.getClosingDate()))throw new IllegalArgumentException("The evaluation policy must be published and effective on the vacancy closing date");String snapshot=serialize(response(agency,policy));PublicationEvaluationPolicy b=bindings.saveAndFlush(new PublicationEvaluationPolicy(agency,publication,policy,snapshot,hash(snapshot),audit.currentActor(),Instant.now()));BindingResponse after=binding(b);audit.record(agency,"BIND_EVALUATION_POLICY","RSP_PUBLICATION_EVALUATION_POLICY",b.getId(),policy.getDefinitionVersion(),b.getVersion(),null,after,null,correlation);return after;}
 private EvaluationPolicy entity(String a,SavePolicy r,int v,String prior){return new EvaluationPolicy(a,r.code(),r.name(),r.description(),r.meritSelectionPlanReference(),v,prior,r.roundingScale(),r.roundingMode(),r.tieRule());}
 private void replace(String agency,EvaluationPolicy p,List<StageInput> inputs){criteria.deleteByAgencyIdAndPolicyId(agency,p.getId());stages.deleteByAgencyIdAndPolicyId(agency,p.getId());stages.flush();for(StageInput input:inputs){EvaluationStage stage=stages.saveAndFlush(stage(agency,p.getId(),input));criteria.saveAll(input.criteria().stream().map(c->criterion(agency,p.getId(),stage.getId(),c)).toList());}criteria.flush();}
 private void copy(String agency,String from,String to){for(EvaluationStage source:stages.findByAgencyIdAndPolicyIdOrderByDisplayOrderAsc(agency,from)){EvaluationStage target=stages.saveAndFlush(new EvaluationStage(agency,to,source.getCode(),source.getName(),source.getInstructions(),source.getType(),source.getMode(),source.getWeight(),source.getMaximumScore(),source.getPassingScore(),source.getMinimumRaters(),source.isRequiresEvidence(),source.getDisplayOrder()));criteria.saveAll(criteria.findByAgencyIdAndStageIdOrderByDisplayOrderAsc(agency,source.getId()).stream().map(c->new EvaluationCriterion(agency,to,target.getId(),c.getCode(),c.getLabel(),c.getInstructions(),c.getWeight(),c.getMaximumScore(),c.isRequiresRemarks(),c.getDisplayOrder())).toList());}criteria.flush();}
 private EvaluationStage stage(String a,String p,StageInput s){return new EvaluationStage(a,p,s.code(),s.name(),s.instructions(),s.type(),s.mode(),s.weight(),s.maximumScore(),s.passingScore(),s.minimumRaters(),s.requiresEvidence(),s.displayOrder());}
 private EvaluationCriterion criterion(String a,String p,String s,CriterionInput c){return new EvaluationCriterion(a,p,s,c.code(),c.label(),c.instructions(),c.weight(),c.maximumScore(),c.requiresRemarks(),c.displayOrder());}
 private void validate(List<StageInput> values){unique(values,StageInput::code,StageInput::displayOrder,"stage");BigDecimal scored=BigDecimal.ZERO;for(StageInput s:values){boolean panel=s.type()==EvaluationStage.Type.COMPETENCY_BASED_INTERVIEW||s.type()==EvaluationStage.Type.BEHAVIORAL_EVENT_INTERVIEW;if(s.mode()==EvaluationStage.Mode.SCORED){scored=scored.add(s.weight());if(panel&&s.criteria().stream().anyMatch(c->c.maximumScore()==null))throw new IllegalArgumentException("Every interview criterion requires a maximum score");if(!panel&&s.maximumScore()==null)throw new IllegalArgumentException("A scored examination stage requires a maximum score");}unique(s.criteria(),CriterionInput::code,CriterionInput::displayOrder,"criterion");BigDecimal criterionWeight=s.criteria().stream().map(CriterionInput::weight).reduce(BigDecimal.ZERO,BigDecimal::add);if(s.mode()==EvaluationStage.Mode.SCORED&&criterionWeight.compareTo(new BigDecimal("100"))!=0)throw new IllegalArgumentException("Scored-stage criterion weights must total 100");if(s.mode()!=EvaluationStage.Mode.SCORED&&criterionWeight.signum()!=0)throw new IllegalArgumentException("Gate and informational criterion weights must total zero");}if(scored.compareTo(new BigDecimal("100"))!=0)throw new IllegalArgumentException("Scored-stage weights must total 100");}
 private void validatePersisted(String agency,String policy){List<EvaluationStage> ss=stages.findByAgencyIdAndPolicyIdOrderByDisplayOrderAsc(agency,policy);if(ss.isEmpty())throw new IllegalArgumentException("A policy requires stages");BigDecimal total=ss.stream().filter(s->s.getMode()==EvaluationStage.Mode.SCORED).map(EvaluationStage::getWeight).reduce(BigDecimal.ZERO,BigDecimal::add);if(total.compareTo(new BigDecimal("100"))!=0)throw new IllegalArgumentException("Scored-stage weights must total 100");for(EvaluationStage s:ss){List<EvaluationCriterion> cs=criteria.findByAgencyIdAndStageIdOrderByDisplayOrderAsc(agency,s.getId());if(cs.isEmpty())throw new IllegalArgumentException("Every stage requires criteria");BigDecimal c=cs.stream().map(EvaluationCriterion::getWeight).reduce(BigDecimal.ZERO,BigDecimal::add);if(s.getMode()==EvaluationStage.Mode.SCORED&&c.compareTo(new BigDecimal("100"))!=0||s.getMode()!=EvaluationStage.Mode.SCORED&&c.signum()!=0)throw new IllegalArgumentException("Criterion weights are inconsistent with stage mode");}}
 private <T>void unique(List<T> values,Function<T,String> code,ToIntFunction<T> order,String label){Set<String> codes=new HashSet<>();Set<Integer> orders=new HashSet<>();for(T v:values)if(!codes.add(code.apply(v).trim().toUpperCase(Locale.ROOT))||!orders.add(order.applyAsInt(v)))throw new IllegalArgumentException("Duplicate "+label+" code or displayOrder");}
 private PolicyResponse response(String agency,EvaluationPolicy p){List<StageResponse> ss=stages.findByAgencyIdAndPolicyIdOrderByDisplayOrderAsc(agency,p.getId()).stream().map(s->new StageResponse(s.getId(),s.getCode(),s.getName(),s.getInstructions(),s.getType().name(),s.getMode().name(),s.getWeight(),s.getMaximumScore(),s.getPassingScore(),s.getMinimumRaters(),s.isRequiresEvidence(),s.getDisplayOrder(),criteria.findByAgencyIdAndStageIdOrderByDisplayOrderAsc(agency,s.getId()).stream().map(c->new CriterionResponse(c.getId(),c.getCode(),c.getLabel(),c.getInstructions(),c.getWeight(),c.getMaximumScore(),c.isRequiresRemarks(),c.getDisplayOrder())).toList())).toList();return new PolicyResponse(p.getId(),p.getCode(),p.getName(),p.getDescription(),p.getMeritSelectionPlanReference(),p.getDefinitionVersion(),p.getSupersedesId(),p.getStatus().name(),p.getEffectiveFrom(),p.getEffectiveTo(),p.getRoundingScale(),p.getRoundingMode().name(),p.getTieRule().name(),p.getAggregationMode().name(),p.getPublishedBy(),p.getPublishedAt(),p.getVersion(),ss);}
 private BindingResponse binding(PublicationEvaluationPolicy b){return new BindingResponse(b.getId(),b.getPublication().getId(),b.getPolicy().getId(),b.getPolicy().getCode(),b.getPolicy().getDefinitionVersion(),b.getPolicyFingerprint(),b.getBoundBy(),b.getBoundAt(),b.getVersion());}
 private EvaluationPolicy policy(String agency,String id){return policies.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Evaluation policy not found"));}
 private static void page(int p,int s){if(p<0||s<1||s>100)throw new IllegalArgumentException("Invalid pagination");} private static void version(long a,Long e){if(e==null||a!=e)throw new OptimisticConflictException("Expected recordVersion "+e+" but current version is "+a);} private String serialize(Object v){try{return json.writeValueAsString(v);}catch(JsonProcessingException e){throw new IllegalStateException("Snapshot could not be serialized",e);}} public static String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
